const filter=process.env.BEND_MUTATION_FILTER;
const from=process.env.BEND_MUTATION_FROM;
const offset=from?mutations.findIndex(([name])=>name===from):0;
if(offset<0)throw new Error('Unknown mutation start: '+from);
const scope=mutations.slice(offset);
const countText=process.env.BEND_MUTATION_COUNT;
if(countText&&(!/^[1-9][0-9]*$/.test(countText)||!Number.isSafeInteger(Number(countText))))throw new Error('Mutation count must be a positive safe integer');
const limited=countText?scope.slice(0,Number(countText)):scope;
const selected=filter?limited.filter(([name])=>name.includes(filter)):limited;
if(selected.length===0)throw new Error('Mutation filter matched no variants');
// Validate operation targets before paying for any compiled variant. A stale
// anchor is infrastructure failure, never evidence of useful mutation rejection.
const sources=new Map(await Promise.all([...new Set(selected.map(row=>row[1]))].map(async file=>[file,await fs.readFile(path.join(root,file),'utf8')])));
for(const [name,file,before,after,test,anchor]of selected){
 const source=sources.get(file),start=anchor?source.indexOf('def '+anchor+'('):0;
 if(start<0)throw new Error('Stale mutation function '+name);
 const next=anchor?source.indexOf('\ndef ',start+1):-1,end=next<0?source.length:next;
 if(source.slice(start,end).split(before).length!==2)throw new Error('Mutation must select exactly one source operation: '+name);
}
if(process.env.BEND_MUTATION_VALIDATE_ONLY){console.log(`${selected.length} mutation operation targets are current; no semantic test was run.`);process.exit(0);}
// An already failing kernel oracle cannot establish a mutant rejection. Check
// each selected kernel module on the unchanged runtime before compiling mutants.
const baselineModules=new Map();
for(const [name,file,before,after,test,anchor,proofModule] of selected)if(proofModule)baselineModules.set(proofModule,test);
const {BEND_EMIT_FILE:ignoredMutationInput,...baselineEnvironment}=process.env;
for(const [proofModule,test] of baselineModules){
 const baseline=spawnSync(process.execPath,[test],{cwd:root,env:{...baselineEnvironment,BEND_PROOF_MODULE:proofModule},encoding:'utf8',maxBuffer:1024*1024});
 if(baseline.status!==0)throw new Error('PROBE_PRECONDITION_FAILED: unchanged kernel oracle '+proofModule+' must pass before mutation credit\n'+baseline.stdout.slice(-1000)+'\n'+baseline.stderr.slice(-3000));
}
let caught=0;
for(const [name,file,before,after,test='tests/differential.mjs',anchor,proofModule] of selected) {
  const dir=await fs.mkdtemp(path.join(os.tmpdir(),'bend-signals-mutation-'));
  try {
    for(const d of ['runtime','representation','observation'])await fs.cp(path.join(root,d),path.join(dir,d),{recursive:true});
    const p=path.join(dir,file),text=await fs.readFile(p,'utf8');
    const start=anchor?text.indexOf('def '+anchor+'('):0;
    if(start<0)throw new Error('Stale mutation function '+name);
    const next=anchor?text.indexOf('\ndef ',start+1):-1,end=next<0?text.length:next;
    const segment=text.slice(start,end);
    if(segment.split(before).length!==2)throw new Error('Mutation must select exactly one source operation: '+name);
    await fs.writeFile(p,text.slice(0,start)+segment.replace(before,after)+text.slice(end));
    const emit=path.join(dir,'runtime.mjs');
    const compile=spawnSync(path.join(root,'node_modules/.bin/bun'),[path.join(root,'upstream/bend/bend2/main.ts'),path.join(dir,'runtime/api.bend'),'-o',emit],{encoding:'utf8'});
    if(compile.status!==0)throw new Error('Mutation did not compile: '+name+'\n'+compile.stderr.slice(-3000));
    const run=spawnSync(process.execPath,[test],{cwd:root,env:{...process.env,BEND_EMIT_FILE:emit,...(proofModule?{BEND_PROOF_MODULE:proofModule}:{})},encoding:'utf8',maxBuffer:1024*1024});
    if(run.status===0)throw new Error('Test oracle accepted mutation: '+name);
    if(run.stderr.includes('PROBE_PRECONDITION_FAILED'))throw new Error('Mutation probe precondition failed: '+name+'\n'+run.stderr.slice(-3000));
    if(!proofModule && /SOME PROOFS FAIL|kernel terminated|out of memory|CompileError|ParseError/.test(run.stdout+run.stderr))throw new Error('Mutation probe failed to compile or exhausted resources: '+name+'\n'+run.stderr.slice(-1500));
    if(!run.stderr.includes('AssertionError'))throw new Error('Mutation failed for an unrelated reason: '+name+'\n'+run.stderr.slice(-3000));
    caught++;console.log('Rejected mutation: '+name);
  } finally {await fs.rm(dir,{recursive:true,force:true});}
}
console.log(`${caught} source-changing variants rejected by differential or kernel assertions.`);
